// The header-tests and layout-tests generators (design §11): their text, from
// the golden model, and the compile matrix over the fixture headers. Every
// generated file compiles with clang and MSVC for x64, x86, and ARM64, and a
// wrong fact fails exactly the targets it's wrong for.

import assert from "node:assert/strict";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { before, test } from "node:test";
import { compileJobs, compileUnits, msvcEnvs } from "../src/compile.ts";
import { StelaError } from "../src/errors.ts";
import { type GeneratedFile, generate, includeSpelling } from "../src/generators.ts";
import { type Model, readModel } from "../src/model.ts";
import { DEFAULT_TEMPLATE } from "../src/stela.ts";
import { findToolchain, runJobs, type Toolchain } from "../src/toolchain.ts";
import { generateLibraryHeader, parseTemplate } from "../src/vendor.ts";
import { modelFixture, runCli } from "./helpers.ts";

const goldenModel = path.join(import.meta.dirname, "golden", "model-demo.json");
const model = readModel(goldenModel);
let toolchain: Toolchain | string = "not probed";

before(async () => {
  toolchain = await findToolchain();
});

const text = (files: GeneratedFile[], file: string) => {
  const found = files.find((f) => f.path === file);
  assert.ok(found, `${file} not generated`);
  return found.text;
};

/** The lines between `#if <guard>` for `target` and its `#endif`. */
function targetBlock(source: string, target: string): string {
  const start = source.indexOf(`/* ${target} */`);
  if (start < 0) return "";
  return source.slice(start, source.indexOf("#endif", start));
}

test("header-tests: one C and one C++ file per entry header and per stela header", () => {
  const files = generate("header-tests", model);
  assert.deepEqual(
    files.map((f) => f.path),
    [
      "demo/demo.header.c",
      "demo/demo.header.cpp",
      "demo/demo_stela.header.c",
      "demo/demo_stela.header.cpp",
      "demo_ext/demo_ext.header.c",
      "demo_ext/demo_ext.header.cpp",
    ],
  );
  const ext = text(files, "demo_ext/demo_ext.header.c");
  assert.match(ext, /^\/\* Generated by Stela \(header-tests\)/);
  assert.match(ext, /^#define DEMO_EXT_EXPERIMENTAL\n#include "demo_ext.h"\n#include "demo_ext.h"\n/m);
  assert.equal(ext, text(files, "demo_ext/demo_ext.header.cpp"));
  assert.doesNotMatch(text(files, "demo/demo.header.c"), /#define/);
  const stela = text(files, "demo/demo_stela.header.c");
  assert.match(stela, /^#include "demo_stela.h"\n#include "demo_stela.h"\n/m);
  assert.equal(stela.match(/#include/g)?.length, 2);
});

test("layout-tests: sizes, alignments, offsets, and enumerator values per target", () => {
  const files = generate("layout-tests", model);
  assert.deepEqual(
    files.map((f) => f.path),
    ["demo/layout.c", "demo/layout.cpp", "demo_ext/layout.c", "demo_ext/layout.cpp"],
  );
  const c = text(files, "demo/layout.c");
  const x64 = targetBlock(c, "x86_64-pc-windows-msvc");
  const x86 = targetBlock(c, "i686-pc-windows-msvc");
  assert.match(c, /^#include "demo.h"$/m);
  assert.match(c, /^_Static_assert\(\(long long\)\(demo_status_failed\) == 28673LL, "value of demo_status_failed"\);$/m);
  assert.match(c, /^#if defined\(_M_X64\) && !defined\(_M_ARM64EC\) \/\* x86_64-pc-windows-msvc \*\/$/m);
  assert.match(x86, /_Static_assert\(sizeof\(struct demo_options\) == 24, /);
  assert.match(x86, /_Static_assert\(_Alignof\(struct demo_options\) == 8, /);
  assert.match(x86, /offsetof\(struct demo_options, name\) == 16, /);
  assert.match(x86, /sizeof\(demo_session\) == 4, /);
  assert.match(x64, /sizeof\(demo_session\) == 8, /);
  // A tag-less struct is spelled by its typedef.
  assert.match(x64, /sizeof\(demo_point\) == 8, /);
  assert.doesNotMatch(c, /struct demo_point/);
  // Bit-fields have no offsetof; incomplete structs have no layout.
  assert.match(x64, /offsetof\(struct demo_bits, tail\) == 8, /);
  assert.doesNotMatch(c, /offsetof\(struct demo_bits, (ready|mode)\)/);
  assert.doesNotMatch(c, /demo_session_s/);
  // A partial declaration appears only for its targets.
  assert.match(x64, /sizeof\(struct demo_wide\) == 16/);
  assert.match(targetBlock(c, "aarch64-pc-windows-msvc"), /sizeof\(struct demo_wide\) == 16/);
  assert.doesNotMatch(x86, /demo_wide/);

  const cpp = text(files, "demo/layout.cpp");
  assert.match(cpp, /^static_assert\(alignof\(struct demo_options\) == 8, "alignment of struct demo_options on x86_64/m);
  assert.doesNotMatch(cpp, /_Static_assert|_Alignof/);

  const ext = text(files, "demo_ext/layout.c");
  assert.match(ext, /^#define DEMO_EXT_EXPERIMENTAL$/m);
  assert.match(
    ext,
    /^#if !\(defined\(_M_X64\) && !defined\(_M_ARM64EC\)\) && !\(defined\(_M_ARM64\)\)\n#error "stela: the model of demo_ext has no layout for this target"$/m,
  );
  assert.doesNotMatch(ext, /i686/);
});

test("generator errors", () => {
  assert.throws(() => generate("bogus", model), StelaError);
  const [library] = model.libraries;
  assert.equal(includeSpelling(library, "include/demo.h"), "demo.h");
  assert.throws(() => includeSpelling(library, "other/demo.h"), /no include directory holds/);
  const odd: Model = { ...model, targets: ["riscv64-unknown-linux-gnu"], libraries: [{ ...library, targets: undefined }] };
  assert.throws(() => generate("layout-tests", odd), /no predefined-macro guard/);
});

test("gen writes the generator's files; usage errors exit with 2", (t) => {
  const root = modelFixture(t, "gen-cli");
  let r = runCli(root, "gen", "layout-tests", "--model", goldenModel, "--out", "gen");
  assert.equal(r.code, 0, r.err);
  assert.equal(
    r.out,
    ["demo/layout.c", "demo/layout.cpp", "demo_ext/layout.c", "demo_ext/layout.cpp"]
      .map((f) => `wrote:     gen/${f}\n`)
      .join(""),
  );
  assert.equal(readFileSync(path.join(root, "gen", "demo", "layout.c"), "utf8"), text(generate("layout-tests", model), "demo/layout.c"));
  r = runCli(root, "gen", "layout-tests", "--model", goldenModel, "--out", "gen");
  assert.match(r.out, /^unchanged: gen\/demo\/layout\.c$/m);

  for (const args of [
    ["gen", "--out", "gen"],
    ["gen", "bogus", "--model", goldenModel, "--out", "gen"],
    ["gen", "layout-tests", "--model", goldenModel],
    // Without --model, gen reads the config's default model, which isn't extracted here.
    ["gen", "layout-tests", "--out", "gen"],
  ]) {
    r = runCli(root, ...args);
    assert.equal(r.code, 2, `${args.join(" ")}: ${r.out}`);
  }
});

async function compileGenerated(
  t: { after(fn: () => void): void },
  mutate: (files: { path: string; text: string }[]) => void,
) {
  if (typeof toolchain === "string") throw new Error(toolchain);
  const root = modelFixture(t, "gen-compile");
  // The fixture's demo library defaults to a stela header; vendor it as `stela vendor` would.
  writeFileSync(
    path.join(root, "include", "demo_stela.h"),
    generateLibraryHeader(parseTemplate(readFileSync(DEFAULT_TEMPLATE, "utf8")), {
      macroPrefix: "DEMO",
      fileName: "demo_stela.h",
    }),
  );
  const out = path.join(root, "gen");
  const files = [...generate("header-tests", model), ...generate("layout-tests", model)].map((f) => ({ ...f }));
  mutate(files);
  for (const f of files) {
    const file = path.join(out, ...f.path.split("/"));
    mkdirSync(path.dirname(file), { recursive: true });
    writeFileSync(file, f.text);
  }
  const units = compileUnits(model, root, out, files);
  const jobs = compileJobs(toolchain, await msvcEnvs(toolchain, units), units);
  const results = await runJobs(jobs);
  return { total: results.length, failed: results.filter((r) => !r.ok) };
}

test("generated tests compile with clang and MSVC on every target", async (t) => {
  if (typeof toolchain === "string") return t.skip(toolchain);
  const { total, failed } = await compileGenerated(t, () => {});
  // demo: 3 files on 3 targets, demo_ext: 1 on 2; each file has 2 clang and 2 MSVC modes.
  assert.equal(total, 6 * 4 * 3 + 4 * 4 * 2);
  assert.deepEqual(
    failed.map((r) => `${r.job.label}\n${r.output}`),
    [],
  );
});

test("a wrong layout fails only its target; a wrong enumerator fails every target", async (t) => {
  if (typeof toolchain === "string") return t.skip(toolchain);
  const { failed } = await compileGenerated(t, (files) => {
    for (const f of files) {
      if (f.path === "demo/layout.c") {
        f.text = f.text.replace(
          'sizeof(struct demo_options) == 24, "size of struct demo_options on i686-pc-windows-msvc"',
          'sizeof(struct demo_options) == 28, "size of struct demo_options on i686-pc-windows-msvc"',
        );
      }
      if (f.path === "demo_ext/layout.cpp") f.text = f.text.replace("== 16, ", "== 20, ");
      if (f.path === "demo/layout.cpp") {
        f.text = f.text.replace("(demo_flags_last) == 1073741824LL", "(demo_flags_last) == 1073741825LL");
      }
    }
  });
  const labels = failed.map((r) => r.job.label).sort();
  const expected = [
    ...["clang x86 c11", "clang x86 c17", "cl x86 /std:c11", "cl x86 /std:c17"].map((l) => `layout.c ${l}`),
    ...["x64", "x86", "arm64"].flatMap((arch) =>
      [`clang ${arch} c++11`, `clang ${arch} c++17`, `cl ${arch} /std:c++14`, `cl ${arch} /std:c++17`].map(
        (l) => `layout.cpp ${l}`,
      ),
    ),
  ];
  // demo_ext's first "== 16" is its x64 size; only x64 fails there.
  const extFailures = failed.filter((r) => r.job.cwd.endsWith("demo_ext")).map((r) => r.job.label).sort();
  assert.deepEqual(
    extFailures,
    ["clang x64 c++11", "clang x64 c++17", "cl x64 /std:c++14", "cl x64 /std:c++17"].map((l) => `layout.cpp ${l}`).sort(),
  );
  const demoFailures = failed.filter((r) => r.job.cwd.endsWith("demo")).map((r) => r.job.label).sort();
  assert.deepEqual(demoFailures, expected.sort());
  assert.equal(labels.length, extFailures.length + demoFailures.length);
  const x86 = failed.find((r) => r.job.label === "layout.c clang x86 c17");
  assert.match(x86!.output, /size of struct demo_options on i686-pc-windows-msvc/);
});
